class ResponseEntriesItem {
  const ResponseEntriesItem({
    required this.index,
    required this.entry,
  });

  /// Read this payload from a decoded JSON object.
  factory ResponseEntriesItem.fromJson(Map<String, dynamic> json) =>
      ResponseEntriesItem(
        index: json['index'] as int,
        entry: json['entry'],
      );

  final int index;
  final BoardEntry entry;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'index': index,
        'entry': entry,
      };
}

/// Voting — Board Read — response payload
class Response {
  const Response({
    required this.treeSize,
    required this.entries,
    this.next,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory Response.fromJson(Map<String, dynamic> json) => Response(
        treeSize: json['treeSize'] as int,
        entries: (json['entries'] as List<dynamic>)
            .map((e) => ResponseEntriesItem.fromJson(e as Map<String, dynamic>))
            .toList(),
        next: json['next'] as int?,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  /// The tree size the page was read against. No entry at or beyond it is returned.
  final int treeSize;

  /// Consecutive entries from `from`, in board order.
  final List<ResponseEntriesItem> entries;

  /// The `from` of the next page. Absent when the page reaches `treeSize`.
  final int? next;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'treeSize': treeSize,
        'entries': entries.map((e) => e.toJson()).toList(),
        if (next != null) 'next': next!,
        if (ext != null) 'ext': ext!,
      };
}

/// Reads a range of an election board's entries, against the current head or against
/// an earlier tree size.
class Payload {
  const Payload({
    required this.community,
    required this.electionId,
    required this.from,
    required this.limit,
    this.treeSize,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory Payload.fromJson(Map<String, dynamic> json) => Payload(
        community: json['community'] as String,
        electionId: json['electionId'] as String,
        from: json['from'] as int,
        limit: json['limit'] as int,
        treeSize: json['treeSize'] as int?,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  /// The community's DID.
  final String community;
  final ElectionId electionId;

  /// The index of the first entry to return.
  final int from;

  /// The most entries to return.
  final int limit;

  /// Read against the board as it stood at this size — the size of a head the reader
  /// holds. At most the current size. Absent: the current size.
  final int? treeSize;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'community': community,
        'electionId': electionId,
        'from': from,
        'limit': limit,
        if (treeSize != null) 'treeSize': treeSize!,
        if (ext != null) 'ext': ext!,
      };
}

