ctiveProof"}}},"DisjunctiveProof":{"title":"DisjunctiveProof","description":"A disjunctive proof that a ciphertext encrypts one value of a public list: one `(c, z)` per value, in the list\'s order (CONVENTIONS §9.3).","type":"array","minItems":1,"maxItems":65,"items":{"\$ref":"#/\$defs/SigmaProof"}},"EncryptedOption":{"title":"EncryptedOption","type":"object","additionalProperties":false,"required":["ciphertext","proof"],"properties":{"ciphertext":{"\$ref":"#/\$defs/ElGamalCiphertext"},"proof":{"\$ref":"#/\$defs/DisjunctiveProof"}}},"ElectionResult":{"title":"ElectionResult","description":"An election\'s result, computable by anyone who can read its board from the board and the registration alone (VTI-VOT-070).","type":"object","additionalProperties":false,"required":["electionId","manifestDigest","ballotsCounted","questions","head"],"properties":{"electionId":{"\$ref":"#/\$defs/ElectionId"},"manifestDigest":{"\$ref":"#/\$defs/DigestMultibase"},"ballotsCounted":{"type":"integer","minimum":0},"questions":{"type":"array","items":{"\$ref":"#/\$defs/QuestionResult"}},"head":{"\$ref":"#/\$defs/BoardHead","description":"The head of the board as it stood at close: the result counts exactly its entries."}}},"BoardHead":{"title":"BoardHead","description":"A board\'s tree head (RFC 9162 §2.1). A head is signed by being carried in a document the ballot box signs; whoever keeps a head keeps that whole document.","type":"object","additionalProperties":false,"required":["electionId","treeSize","rootHash","issuedAt"],"properties":{"electionId":{"\$ref":"#/\$defs/ElectionId"},"treeSize":{"type":"integer","minimum":0},"rootHash":{"\$ref":"#/\$defs/DigestMultibase","description":"The RFC 9162 Merkle tree hash (SHA-256) of the first `treeSize` entries, as a multihash."},"issuedAt":{"type":"string","format":"date-time"}}},"QuestionResult":{"title":"QuestionResult","description":"One question\'s totals. `choice`: selections per option. `ranking`: per option, how many ballots placed it a