:["sum","count"],"properties":{"sum":{"type":"integer"},"count":{"type":"integer","minimum":0}}}},"text":{"type":"array","items":{"type":"string","maxLength":4096}},"withheld":{"type":"boolean"}}},"Cast":{"title":"Cast","description":"A ballot and the PCS attestation that admits it (VTI-VOT-030). `attestation` is the suite\'s canonical encoding of the attestation made for the election point with the ballot context bound in (CONVENTIONS §3); `tag` repeats its tag so a ballot box can refuse a duplicate before the pairing check.","type":"object","additionalProperties":false,"required":["ballot","tag","attestation"],"properties":{"ballot":{"\$ref":"#/\$defs/Ballot"},"tag":{"\$ref":"#/\$defs/Multibase"},"attestation":{"\$ref":"#/\$defs/Multibase"}}}}}';

